window.products.push({"id":968885,"name":"Christmas Jingle Juice Pint Glass - The Perfect Stocking Stuffer","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51yDkpfDNsL._AC_SL1000_.jpg","description":"'Tis the holiday season and time to get ready for your holiday festivities! This Jingle Juice pint glass can be left by the fireplace for Santa, brought to your office holiday party or family holiday party, given as a stocking stuffer or left as a gift under the Christmas Tree. Try the Jingle Juice recipe, or fill it with milk for Santa, or pour your drink of choice and put some Jingle in your step! It is the most wonderful time of the year, so fill up with some Jingle Juice and have a Merry Christmas!","images":["https://m.media-amazon.com/images/I/51yDkpfDNsL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"The Plympton Company","source_asin":"B07786XSKK","category_path":"Home & Kitchen"},"sku":"BM-968885","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07786XSKK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07786XSKK","price_pending":true,"merchant_ready":false});
